756	/// Split a local-link destination into `(normalized_path_text, location_suffix)`.
757	///
758	/// The returned path text never includes a trailing `#L..` or `:line[:col]` suffix. Path
759	/// normalization expands `~/...` when possible and rewrites path separators into display-stable
760	/// forward slashes. The suffix, when present, is returned separately in normalized markdown form.
761	///
762	/// Returns `None` only when the destination looks like a `file://` URL but cannot be parsed into a
763	/// local path. Plain path-like inputs always return `Some(...)` even if they are relative.
764	fn parse_local_link_target(dest_url: &str) -> Option<(String, Option<String>)> {
765	    if dest_url.starts_with("file://") {
766	        let url = Url::parse(dest_url).ok()?;
767	        let path_text = file_url_to_local_path_text(&url)?;
768	        let location_suffix = url
769	            .fragment()
770	            .and_then(normalize_hash_location_suffix_fragment);
771	        return Some((path_text, location_suffix));
772	    }
773	
774	    let mut path_text = dest_url;
775	    let mut location_suffix = None;
776	    // Prefer `#L..` style fragments when both forms are present so URLs like `path#L10` do not
777	    // get misparsed as a plain path ending in `:10`.
778	    if let Some((candidate_path, fragment)) = dest_url.rsplit_once('#')
779	        && let Some(normalized) = normalize_hash_location_suffix_fragment(fragment)
780	    {
781	        path_text = candidate_path;
782	        location_suffix = Some(normalized);
783	    }
784	    if location_suffix.is_none()
785	        && let Some(suffix) = extract_colon_location_suffix(path_text)
786	    {
787	        let path_len = path_text.len().saturating_sub(suffix.len());
788	        path_text = &path_text[..path_len];
789	        location_suffix = Some(suffix);
790	    }
791	
792	    Some((expand_local_link_path(path_text), location_suffix))
793	}
