796	///
797	/// Returns `None` for fragments that are not location references. This deliberately ignores other
798	/// `#...` fragments so non-location hashes stay part of the path text.
799	fn normalize_hash_location_suffix_fragment(fragment: &str) -> Option<String> {
800	    HASH_LOCATION_SUFFIX_RE
801	        .is_match(fragment)
802	        .then(|| format!("#{fragment}"))
803	        .and_then(|suffix| normalize_markdown_hash_location_suffix(&suffix))
