806	/// Extract a trailing `:line`, `:line:col`, or range suffix from a plain path-like string.
807	///
808	/// The suffix must occur at the end of the input; embedded colons elsewhere in the path are left
809	/// alone. This is what keeps Windows drive letters like `C:/...` from being misread as locations.
810	fn extract_colon_location_suffix(path_text: &str) -> Option<String> {
811	    COLON_LOCATION_SUFFIX_RE
812	        .find(path_text)
813	        .filter(|matched| matched.end() == path_text.len())
814	        .map(|matched| matched.as_str().to_string())
815	}
