818	///
819	/// If `~/...` cannot be expanded because the home directory is unavailable, the original text still
820	/// goes through separator normalization and is returned as-is otherwise.
821	fn expand_local_link_path(path_text: &str) -> String {
822	    // Expand `~/...` eagerly so home-relative links can participate in the same normalization and
823	    // cwd-relative shortening path as absolute links.
824	    if let Some(rest) = path_text.strip_prefix("~/")
825	        && let Some(home) = home_dir()
826	    {
827	        return normalize_local_link_path_text(&home.join(rest).to_string_lossy());
828	    }
