833	/// Convert a `file://` URL into the normalized local-path text used for transcript rendering.
834	///
835	/// This prefers `Url::to_file_path()` for standard file URLs. When that rejects Windows-oriented
836	/// encodings, we reconstruct a display path from the host/path parts so UNC paths and drive-letter
837	/// URLs still render sensibly.
838	fn file_url_to_local_path_text(url: &Url) -> Option<String> {
839	    if let Ok(path) = url.to_file_path() {
840	        return Some(normalize_local_link_path_text(&path.to_string_lossy()));
841	    }
842	
