/// Render a generated image's saved path as a `file://` URI for display.
///
/// Paths that are already `file://` URIs are passed through untouched. Plain filesystem paths are
/// converted with [`Url::from_file_path`], falling back to the original value if conversion fails.
fn saved_path_to_file_uri(saved_to: &str) -> String {
    if saved_to.starts_with("file://") {
        return saved_to.to_string();
    }

    url::Url::from_file_path(saved_to)
        .map(|url| url.to_string())
        .unwrap_or_else(|_| saved_to.to_string())
}

